package com.openggf.game.soniccd.level;
import com.openggf.game.soniccd.*;
import com.openggf.game.soniccd.media.CdMmdImage;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Tests FIRST; immutable source relation only. No R31 Frame/Body/World or gameplay admission. */
class TestCdR31aStagePlayerSource {
 @Test void actualR31RelationHasNative0100PresentAndExactSameBorrowedProducts()throws Exception{var a=TestCdR31aPlayerCoreAssets.actual().first();var source=CdStagePlayerSource.fromR31aAssets(a);assertTrue(source.ownsR31aAssets(a));assertEquals(CdReleaseVariant.USA,source.variant());assertEquals(CdStagePayload.R31A.stage(),source.stage());assertEquals(0x100,source.ordinaryZoneActWord());assertEquals(1,source.ordinaryPeriod());assertEquals(0x22DF20,source.mappingAddress());assertEquals(a.range(CdR31aAssets.Asset.MAP_SPR_SONIC).nativeAddress(),source.mappingAddress());assertSame(a.terrain(),source.terrain());assertSame(a.sonic(),source.sonic());assertSame(source.player(),source.player());assertSame(source.sonic(),source.player().sonic());assertTrue(source.player().ownsR31aAssets(a));assertEquals(CdR11aPlayerAssets.SourceGraph.R3,source.player().sourceGraph());assertEquals(CdStageTerrain.Shape.CCZ1_PRESENT,source.terrain().shape());assertThrows(CdR11aPlayerAssets.UnownedPpzRamp.class,source.player()::rampChunks);}
 @Test void independentEqualOriginalOwnersStayDistinctAndNeverAcquireOldFamilies()throws Exception{var actual=TestCdR31aPlayerCoreAssets.actual();var a=CdStagePlayerSource.fromR31aAssets(actual.first());var b=CdStagePlayerSource.fromR31aAssets(actual.second());assertEquals(actual.first().identity(),actual.second().identity());assertTrue(a.ownsR31aAssets(actual.first()));assertFalse(a.ownsR31aAssets(actual.second()));assertTrue(b.ownsR31aAssets(actual.second()));assertFalse(b.ownsR31aAssets(actual.first()));assertFalse(a.ownsR31aAssets(null));assertFalse(a.ownsPresent(actual.present()));assertFalse(a.ownsPast(null));assertFalse(a.ownsAct2(null,null));assertFalse(a.ownsAct2Past(null,null));assertFalse(a.ownsAct3Future(null));assertNotSame(a.player(),b.player());assertNotSame(a.sonic(),b.sonic());assertArrayEquals(a.player().animationTable().copy(),b.player().animationTable().copy());}
 @Test void originalPresentRelationAndItsRampStayOwnedByTheOldSource()throws Exception{var actual=TestCdR31aPlayerCoreAssets.actual();var source=CdStagePlayerSource.fromPresent(actual.present());assertTrue(source.ownsPresent(actual.present()));assertFalse(source.ownsR31aAssets(actual.first()));assertEquals(0,source.ordinaryZoneActWord());assertEquals(1,source.ordinaryPeriod());assertSame(actual.present().player(),source.player());assertSame(actual.present().sonic(),source.sonic());assertEquals(CdR11aPlayerAssets.SourceGraph.PPZ,source.player().sourceGraph());assertEquals(6,source.player().rampChunks().length());}
 @Test void mismatchedTerrainVisualOrOriginalMappingRangeIsRejected()throws Exception{var actual=TestCdR31aPlayerCoreAssets.actual();var wrongTerrain=spy(actual.first());doReturn(actual.present().terrain().stageTerrain()).when(wrongTerrain).terrain();assertThrows(IllegalArgumentException.class,()->CdStagePlayerSource.fromR31aAssets(wrongTerrain));var wrongVisual=spy(actual.first());doReturn(actual.present().sonic()).when(wrongVisual).sonic();assertThrows(IllegalArgumentException.class,()->CdStagePlayerSource.fromR31aAssets(wrongVisual));var wrongMap=spy(actual.first());doReturn(actual.first().range(CdR31aAssets.Asset.DPLC_SONIC)).when(wrongMap).range(CdR31aAssets.Asset.MAP_SPR_SONIC);assertThrows(IllegalArgumentException.class,()->CdStagePlayerSource.fromR31aAssets(wrongMap));}
 @Test void sourceNullCannotChooseADefaultAndReadonlyRelationOutlivesClosedMedia()throws Exception{assertThrows(NullPointerException.class,()->CdStagePlayerSource.fromR31aAssets(null));var a=TestCdR31aPlayerCoreAssets.actual().first();var source=CdStagePlayerSource.fromR31aAssets(a);var before=source.player().animationTable().copy();Arrays.fill(source.player().animationTable().copy(),(byte)0xFF);assertArrayEquals(before,source.player().animationTable().copy());assertTrue(source.ownsR31aAssets(a));assertSame(a.sonic(),source.sonic());assertEquals(CdMmdImage.Domain.ORIGINAL_WORD_RAM,a.identity().domain());}
 @Test void newPublicSeamsAreFiniteDataAndOnlyTheTwoSharedTypesChange()throws Exception{var factory=CdStagePlayerSource.class.getDeclaredMethod("fromR31aAssets",CdR31aAssets.class);assertEquals(CdStagePlayerSource.class,factory.getReturnType());assertTrue(java.lang.reflect.Modifier.isStatic(factory.getModifiers()));assertEquals(List.of(java.io.IOException.class),Arrays.asList(factory.getExceptionTypes()));var owner=CdStagePlayerSource.class.getDeclaredField("r3Source");assertEquals(CdProgrammeReader.class,owner.getType());assertThrows(NoSuchFieldException.class,()->CdStagePlayerSource.class.getDeclaredField("r31a"));assertTrue(java.lang.reflect.Modifier.isPrivate(owner.getModifiers()));assertTrue(java.lang.reflect.Modifier.isFinal(owner.getModifiers()));assertEquals(List.of("PPZ","R3"),Arrays.stream(CdR11aPlayerAssets.SourceGraph.values()).map(Enum::name).toList());for(var c:CdR11aPlayerAssets.class.getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(c.getModifiers()));assertTrue(Arrays.stream(CdStagePlayerSource.class.getDeclaredMethods()).noneMatch(m->m.getName().contains("Frame")||m.getName().contains("World")));}
}
